<template>
  <q-page class="game-page"><div class="shell">
    <header class="header"><div class="header-left"><q-btn flat round dense icon="arrow_back" @click="goBack"/><div class="icon"><q-icon name="rule"/></div><div><h1>Verdadero o falso</h1><p>Presenta afirmaciones bíblicas y revela la respuesta correcta.</p></div></div><q-btn v-if="mode==='library'" unelevated no-caps icon="add" label="Nueva actividad" class="primary" @click="createActivity"/><div v-else-if="mode==='editor'" class="actions"><q-btn flat no-caps label="Cancelar" @click="mode='library'"/><q-btn unelevated no-caps icon="save" label="Guardar" class="primary" @click="saveActivity"/></div><div v-else class="actions"><q-badge color="positive">EN VIVO</q-badge><q-btn flat no-caps icon="close" label="Salir" @click="stopGame"/><q-btn unelevated no-caps icon="cast" label="Actualizar" class="primary" @click="sendLive"/></div></header>
    <section v-if="mode==='library'" class="library"><div v-if="!activities.length" class="empty"><q-icon name="rule" size="58px"/><h2>No hay actividades guardadas</h2><p>Crea afirmaciones y define si son verdaderas o falsas.</p><q-btn unelevated no-caps icon="add" label="Crear actividad" class="primary" @click="createActivity"/></div><div v-else class="cards"><article v-for="a in activities" :key="a.id" class="card"><div class="card-icon"><q-icon name="rule"/></div><div class="copy"><h3>{{a.title}}</h3><span>{{a.rounds.length}} preguntas</span></div><q-btn flat round dense icon="edit" @click="editActivity(a)"/><q-btn flat round dense icon="delete_outline" color="red-4" @click="removeActivity(a)"/><q-btn unelevated no-caps icon="play_arrow" label="Abrir" class="primary" @click="playActivity(a)"/></article></div></section>
    <section v-else-if="mode==='editor'" class="editor"><aside><label>Nombre de la actividad</label><q-input v-model="title" dark outlined dense/><div class="round-head"><strong>Afirmaciones</strong><q-btn flat dense no-caps icon="add" label="Agregar" @click="addRound"/></div><button v-for="(r,i) in rounds" :key="r.id" class="round-row" :class="{active:r.id===activeId}" @click="activeId=r.id"><span>{{i+1}}</span><div><strong>{{r.prompt||'Sin afirmación'}}</strong><small>{{r.answer}}</small></div><q-btn v-if="rounds.length>1" flat round dense icon="close" @click.stop="deleteRound(r.id)"/></button></aside><main v-if="activeRound"><div class="field"><label>Afirmación</label><q-input v-model="activeRound.prompt" dark outlined dense autogrow placeholder="Moisés construyó el arca."/></div><div class="field"><label>Respuesta correcta</label><q-btn-toggle v-model="activeRound.answer" spread no-caps unelevated toggle-color="primary" :options="options"/></div><div class="field"><label>Referencia bíblica</label><q-input v-model="activeRound.bibleReference" dark outlined dense placeholder="Génesis 6"/></div><div class="field"><label>Explicación</label><q-input v-model="activeRound.explanation" dark outlined dense autogrow placeholder="El arca fue construida por Noé."/></div><div class="preview"><span>PREVISUALIZACIÓN</span><h2>{{activeRound.prompt||'Escribe una afirmación'}}</h2><div class="choice-preview"><div>VERDADERO</div><div>FALSO</div></div></div></main></section>
    <section v-else class="play"><aside><h2>{{playing?.title}}</h2><p>Pregunta {{playingIndex+1}} de {{playing?.rounds.length??0}}</p><button v-for="(r,i) in playing?.rounds??[]" :key="r.id" class="round-row" :class="{active:i===playingIndex}" @click="setRound(i)"><span>{{i+1}}</span><strong>{{r.bibleReference||`Pregunta ${i+1}`}}</strong></button></aside><main v-if="playingRound" class="stage"><div class="stage-card"><span>VERDADERO O FALSO</span><h1>{{playingRound.prompt}}</h1><div class="big-choices"><button :class="{selected:operatorChoice==='Verdadero',correct:showAnswer&&playingRound.answer==='Verdadero',wrong:showAnswer&&operatorChoice==='Verdadero'&&playingRound.answer!=='Verdadero'}" @click="choose('Verdadero')">VERDADERO</button><button :class="{selected:operatorChoice==='Falso',correct:showAnswer&&playingRound.answer==='Falso',wrong:showAnswer&&operatorChoice==='Falso'&&playingRound.answer!=='Falso'}" @click="choose('Falso')">FALSO</button></div><div v-if="showAnswer" class="answer"><span>RESPUESTA CORRECTA</span><strong>{{playingRound.answer}}</strong><small v-if="playingRound.explanation">{{playingRound.explanation}}</small></div><small class="reference">{{playingRound.bibleReference}}</small></div><div class="controls"><q-btn unelevated no-caps icon="visibility" label="Revelar respuesta" class="primary" @click="revealAnswer"/><q-space/><q-btn flat no-caps icon="arrow_upward" label="Anterior" :disable="playingIndex<=0" @click="move(-1)"/><q-btn unelevated no-caps icon-right="arrow_downward" label="Siguiente" class="primary" :disable="playingIndex>=(playing?.rounds.length??1)-1" @click="move(1)"/></div></main></section>
  </div></q-page>
</template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useQuasar}from'quasar';import{useRouter}from'vue-router';import{createBibleActivityId,deleteBibleActivity,getBibleActivities,saveBibleActivity}from'../services/bible-activity-library';import type{BibleActivityRecord,BibleActivityRound}from'../shared/bible-activities';
type Mode='library'|'editor'|'play';const router=useRouter(),$q=useQuasar();const options=[{label:'Verdadero',value:'Verdadero'},{label:'Falso',value:'Falso'}];const mode=ref<Mode>('library'),activities=ref<BibleActivityRecord[]>([]),editingId=ref<string|null>(null),title=ref(''),rounds=ref<BibleActivityRound[]>([]),activeId=ref(''),playing=ref<BibleActivityRecord|null>(null),playingIndex=ref(0),showAnswer=ref(false),operatorChoice=ref('');const activeRound=computed(()=>rounds.value.find(r=>r.id===activeId.value)??null),playingRound=computed(()=>playing.value?.rounds[playingIndex.value]??null);function fresh(){return{id:createBibleActivityId('true-false-round'),prompt:'',answer:'Verdadero',bibleReference:'',hint:'',explanation:''}}function reload(){activities.value=getBibleActivities('true-false')}function goBack(){if(mode.value!=='library'){stopGame();mode.value='library';return}void router.push('/actividades')}function createActivity(){editingId.value=null;title.value='';rounds.value=[fresh()];activeId.value=rounds.value[0]!.id;mode.value='editor'}function editActivity(a:BibleActivityRecord){editingId.value=a.id;title.value=a.title;rounds.value=a.rounds.map(r=>({...r}));activeId.value=rounds.value[0]?.id??'';mode.value='editor'}function addRound(){const r=fresh();rounds.value.push(r);activeId.value=r.id}function deleteRound(id:string){rounds.value=rounds.value.filter(r=>r.id!==id);activeId.value=rounds.value[0]?.id??''}function saveActivity(){if(!title.value.trim()||rounds.value.some(r=>!r.prompt.trim())){$q.notify({type:'warning',message:'Completa el nombre y todas las afirmaciones.',position:'top'});return}const now=new Date().toISOString(),old=editingId.value?activities.value.find(a=>a.id===editingId.value):null;saveBibleActivity({id:editingId.value??createBibleActivityId('true-false'),type:'true-false',title:title.value.trim(),rounds:rounds.value.map(r=>({...r,prompt:r.prompt.trim(),bibleReference:r.bibleReference.trim()})),createdAt:old?.createdAt??now,updatedAt:now});reload();mode.value='library'}function removeActivity(a:BibleActivityRecord){if(window.confirm(`¿Eliminar “${a.title}”?`)){deleteBibleActivity(a.id);reload()}}function playActivity(a:BibleActivityRecord){playing.value=a;playingIndex.value=0;mode.value='play';resetRound()}function setRound(i:number){playingIndex.value=i;resetRound()}function resetRound(){showAnswer.value=false;operatorChoice.value='';sendLive()}function choose(value:string){operatorChoice.value=value;sendLive()}function revealAnswer(){showAnswer.value=true;sendLive()}function move(d:-1|1){const max=(playing.value?.rounds.length??1)-1;setRound(Math.min(max,Math.max(0,playingIndex.value+d)))}function stopGame(){if(mode.value==='play')window.icpStudio?.projection.setState({mode:'blank'});playing.value=null}function sendLive(){const r=playingRound.value;if(!r||!playing.value)return;const choices='VERDADERO     |     FALSO';window.icpStudio?.projection.setState({mode:'content',title:playing.value.title,body:`${r.prompt}\n\n${choices}${showAnswer.value?`\n\nRespuesta: ${r.answer}${r.explanation?`\n${r.explanation}`:''}`:''}`,footer:r.bibleReference})}onMounted(reload);
</script>
<style scoped>
.game-page{padding:16px;color:#dce7f4;background:#08111c}.shell{min-height:calc(100vh - 98px);background:#0c1521;border:1px solid #25364a;border-radius:14px;overflow:hidden}.header,.header-left,.actions,.card,.round-head,.controls{display:flex;align-items:center}.header{min-height:74px;justify-content:space-between;padding:12px 18px;background:#0d1825;border-bottom:1px solid #25364a}.header-left,.actions{gap:10px}.icon,.card-icon{display:grid;place-items:center;color:#22d3ee;background:#22d3ee16;border:1px solid #22d3ee44}.icon{width:44px;height:44px;border-radius:12px}.header h1,.card h3{margin:0}.header p{margin:4px 0 0;color:#8191a5;font-size:11px}.primary{color:#fff;background:#2563eb}.library{padding:20px}.empty{display:grid;min-height:430px;place-items:center;align-content:center;gap:10px;color:#718399}.cards{display:grid;gap:10px}.card{gap:10px;padding:14px;background:#0d1825;border:1px solid #25384c;border-radius:12px}.card-icon{width:40px;height:40px;border-radius:10px}.copy{flex:1}.copy span{color:#718399}.editor,.play{display:grid;grid-template-columns:330px minmax(0,1fr);min-height:calc(100vh - 174px)}.editor>aside,.play>aside{padding:16px;background:#09131e;border-right:1px solid #25364a}.editor>main,.stage{padding:18px}.editor label,.field label{display:block;margin-bottom:7px}.round-head{justify-content:space-between;margin:18px 0 10px}.round-row{display:flex;width:100%;align-items:center;gap:8px;margin-bottom:6px;padding:9px;color:#c9d5e2;text-align:left;background:#0d1926;border:1px solid #26394e;border-radius:9px}.round-row.active{border-color:#22d3ee}.round-row>span{display:grid;width:26px;height:26px;place-items:center;background:#17283a;border-radius:7px}.round-row>div{display:flex;min-width:0;flex:1;flex-direction:column}.round-row small{color:#718399}.field{margin-bottom:16px}.preview,.stage-card{padding:24px;background:#0d1825;border:1px solid #25384c;border-radius:13px}.preview>span,.stage-card>span{color:#22d3ee;font-size:9px;letter-spacing:.1em}.choice-preview,.big-choices{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}.choice-preview div,.big-choices button{padding:22px;text-align:center;border-radius:12px}.choice-preview div{background:#0b1e2b;border:1px solid #28516a}.big-choices button{color:#e2e8f0;background:#0b1e2b;border:2px solid #28516a;font-size:20px;font-weight:800;cursor:pointer}.big-choices button.selected{border-color:#38bdf8}.big-choices button.correct{color:#bbf7d0;background:#16a34a22;border-color:#22c55e}.big-choices button.wrong{color:#fecaca;background:#dc262622;border-color:#ef4444}.answer{display:flex;flex-direction:column;margin-top:20px;padding:16px;background:#16a34a12;border:1px solid #22c55e55;border-radius:10px}.answer strong{font-size:28px}.reference{display:block;margin-top:18px;color:#94a3b8}.controls{gap:8px;margin-top:12px}@media(max-width:850px){.editor,.play{grid-template-columns:1fr}.choice-preview,.big-choices{grid-template-columns:1fr}}
</style>